def shape(v):
 if isinstance(v,dict):return {'type':'object','additionalProperties':False,'required':list(v),'properties':{k:shape(x) for k,x in v.items()}}
 if isinstance(v,list):
  if not v:return {'type':'array','items':{}}
  ss=[]
  for x in v:
   s=shape(x)
   if s not in ss:ss.append(s)
  return {'type':'array','items':ss[0] if len(ss)==1 else {'anyOf':ss}}
 if v is None:return {'type':'null'}
 if isinstance(v,bool):return {'type':'boolean'}
 if isinstance(v,int):return {'type':'integer'}
 if isinstance(v,float):return {'type':'number'}
 return {'type':'string'}
